import importlib

try:
    import importlib.util
except ImportError:
    pass


try:
    module_from_spec = importlib.util.module_from_spec
except AttributeError:
    def module_from_spec(spec):
        """函数 module_from_spec：处理 spec 相关逻辑。"""
        return spec.loader.load_module(spec.name)
